#!/usr/bin/env python3
"""Offline developer-only subset import. Rust builds do not require fontTools."""
from pathlib import Path
import argparse,hashlib,json,shutil
from fontTools import subset
from fontTools.ttLib import TTFont
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--output',type=Path,default=Path(__file__).resolve().parents[1]);a=p.parse_args()
src=a.source/'shared/src/commonMain/resources/symbols';out=a.output;dest=out/'assets/icons';dest.mkdir(parents=True,exist_ok=True)
names="terminal add content_paste stop bug_report step_over step_into step_out play_arrow build save content_copy smartphone chevron_right refresh code folder folder_open search settings close more_horiz warning article dock_to_bottom check expand_less expand_more pause description animation android folder_zip widgets data_object coffee storage integration_instructions image movie audiotrack tune key verified_user memory text_snippet database developer_board language css html javascript pets diamond schema menu_book table_chart slideshow text_fields inventory_2 difference".split()
index={line.split('\t')[0]:int(line.split('\t')[1],16) for line in(src/'index.tsv').read_text().splitlines() if line and not line.startswith('#')}
points={n:index[n] for n in names};files={}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
for style in ['Filled','Outlined']:
 original=src/f'MaterialSymbolsRounded-{style}.ttf';font=TTFont(original,recalcTimestamp=False);options=subset.Options();options.layout_features=[];options.notdef_glyph=True;options.notdef_outline=True;options.recalc_timestamp=False
 sub=subset.Subsetter(options=options);sub.populate(unicodes=list(points.values()));sub.subset(font);target=dest/f'material-rounded-{style.lower()}.ttf';font.save(target)
 cmap=TTFont(target).getBestCmap();assert all(cp in cmap for cp in points.values())
 files[style]={'source_file':original.name,'source_sha256':sha(original),'subset_file':target.name,'subset_sha256':sha(target),'subset_bytes':target.stat().st_size}
shutil.copy2(src/'LICENSE-MaterialSymbols.txt',dest/'LICENSE-MaterialSymbols.txt')
manifest={'schema':1,'origin':'WEXdesktop/shared/src/commonMain/resources/symbols','modified':'Subset of static Material Symbols Rounded; only listed codepoints retained; layout ligatures removed.','source_index_sha256':sha(src/'index.tsv'),'source_badges_sha256':sha(a.source/'shared/src/commonMain/kotlin/org/wexclient/app/ui/FileIconBadge.kt'),'license_sha256':sha(dest/'LICENSE-MaterialSymbols.txt'),'symbols':points,'fonts':files}
(dest/'manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
(dest/'README.txt').write_text('Material Symbols Rounded, Google, Apache-2.0; license alongside.\nModified: deterministic offline subset of WEXdesktop static Filled/Outlined fonts; no ligatures.\nFile-kind colors adapted from WEXdesktop FileIconBadge.kt.\nNamed icon-only font families; never editor text fallbacks. No JVM or font download.\nRecreate: python3 scripts/import-wex-symbols.py --source /path/to/WEXdesktop\nSee manifest.json for original/subset hashes and retained name/codepoint inventory.\n')
code='//! Local WEXdesktop Material Symbols Rounded subsets; not editor text fallbacks.\n'
for n,cp in points.items():code+=f"pub const {n.upper()}: char = '{chr(92)}u{{{cp:x}}}';\n"
code+='\n#[cfg(feature = "desktop")]\npub fn install(ctx: &eframe::egui::Context) {\n    use eframe::egui::{FontData, FontDefinitions, FontFamily};\n    let mut fonts = FontDefinitions::default();\n    for (name, bytes) in [\n        ("wex-symbols-filled", include_bytes!("../assets/icons/material-rounded-filled.ttf").as_slice()),\n        ("wex-symbols-outlined", include_bytes!("../assets/icons/material-rounded-outlined.ttf").as_slice()),\n    ] {\n        fonts.font_data.insert(name.into(), FontData::from_static(bytes).into());\n        fonts.families.insert(FontFamily::Name(name.into()), vec![name.into()]);\n    }\n    ctx.set_fonts(fonts);\n}\n#[cfg(feature = "desktop")]\npub fn paint(ui: &eframe::egui::Ui, rect: eframe::egui::Rect, glyph: char, color: eframe::egui::Color32, filled: bool) {\n    use eframe::egui::{Align2, FontFamily, FontId};\n    let family = if filled { "wex-symbols-filled" } else { "wex-symbols-outlined" };\n    ui.painter().text(rect.center(), Align2::CENTER_CENTER, glyph, FontId::new(rect.width().min(rect.height()), FontFamily::Name(family.into())), color);\n}\n#[cfg(all(test, feature = "desktop"))]\nmod tests {\n    use super::*;\n    use ab_glyph::{Font, FontRef};\n    #[test]\n    fn every_imported_symbol_has_real_outline_in_both_fonts() {\n        let manifest: serde_json::Value = serde_json::from_str(include_str!("../assets/icons/manifest.json")).unwrap();\n        for bytes in [include_bytes!("../assets/icons/material-rounded-filled.ttf").as_slice(),include_bytes!("../assets/icons/material-rounded-outlined.ttf").as_slice()] {\n            let font=FontRef::try_from_slice(bytes).unwrap();\n            for cp in manifest["symbols"].as_object().unwrap().values() {\n                let glyph=font.glyph_id(char::from_u32(cp.as_u64().unwrap() as u32).unwrap());\n                assert_ne!(glyph.0,0);assert!(font.outline(glyph).is_some());\n            }\n        }\n    }\n    #[test]\n    fn icon_install_keeps_default_source_font_families_exactly_unchanged() {\n        use eframe::egui::{Context, FontDefinitions, FontFamily};\n        let ctx=Context::default();install(&ctx);\n        let _=ctx.run(Default::default(), |ctx| {\n            let actual=ctx.fonts(|f|f.definitions().clone());\n            let original=FontDefinitions::default();\n            for family in [FontFamily::Monospace,FontFamily::Proportional] {assert_eq!(actual.families[&family],original.families[&family]);}\n            assert_eq!(actual.font_data.len(),original.font_data.len()+2);\n        });\n    }\n}\n'
(out/'src').mkdir(parents=True,exist_ok=True)
(out/'src/material_symbols.rs').write_text(code)
print('LOCAL_SYMBOLS_IMPORTED: '+str(len(points))+' glyphs per style; '+str(sum(x['subset_bytes'] for x in files.values()))+' font bytes; offline')
